const API="/api";
async function apiFetch(route,options={}){const headers=new Headers(options.headers||{});if(options.method&&options.method!=="GET"&&window.demoAuth?.csrf)headers.set("X-CSRF-Token",window.demoAuth.csrf);const response=await fetch(API+route,{...options,headers,credentials:"same-origin",cache:"no-store"});if(response.status===401)window.dispatchEvent(new Event("auth-required"));return response}
const MAX_BYTES=2000*1000*1000,allowed=new Set(["wav","flac","m4a"]);
const input=document.querySelector("#audio-file"),zone=document.querySelector("#drop-zone"),result=document.querySelector("#file-result"),error=document.querySelector("#upload-error"),nameEl=document.querySelector("#file-name"),metaEl=document.querySelector("#file-meta"),fileState=document.querySelector("#file-state"),fileRemove=document.querySelector("#file-remove"),preview=document.querySelector("#preview-player"),audio=document.querySelector("#audio-preview"),previewStatus=document.querySelector("#preview-status"),uploadButton=document.querySelector("#upload-button"),progress=document.querySelector("#upload-progress"),fill=document.querySelector("#progress-fill"),percent=document.querySelector("#progress-percent"),progressText=document.querySelector("#progress-text");
const analyzeButton=document.querySelector("#analyze-button"),analysisStatus=document.querySelector("#analysis-status"),analysisState=document.querySelector("#analysis-state"),analysisText=document.querySelector("#analysis-text");
const trackResults=document.querySelector("#track-results"),trackCount=document.querySelector("#track-count"),trackList=document.querySelector("#track-list");
const waveformPanel=document.querySelector("#waveform-panel"),waveformWrap=document.querySelector("#waveform-wrap"),waveformCanvas=document.querySelector("#waveform-canvas"),waveformTime=document.querySelector("#waveform-time");
const exportPanel=document.querySelector("#export-panel"),exportFormat=document.querySelector("#export-format"),exportButton=document.querySelector("#export-button"),exportStatus=document.querySelector("#export-status"),downloadList=document.querySelector("#download-list"),deleteExportButton=document.querySelector("#delete-export-button");
let processingEpoch=0,pendingUploadId=null,uploadsRequest=0;
let objectUrl=null,selectedFile=null,uploadedFileId=null,activeTrackEnd=null,activePlayButton=null,lastAnalysis=null,currentExportJobId=null,editableBoundaries=[],previewMode="local",previewProbe=null,previewPreparing=false;
function setProgress(value,text){const p=Math.max(0,Math.min(100,value));fill.style.width=p+"%";percent.textContent=Math.floor(p)+"%";progressText.textContent=text}
function setFileLocation(onModify){fileState.textContent=onModify?"ON MODIFY":"READY";fileRemove.textContent=onModify?"Remove from Modify":"Remove"}
function setFileRemoveBusy(busy,label="Processing…"){fileRemove.disabled=busy;if(busy)fileRemove.textContent=label;else setFileLocation(Boolean(uploadedFileId||pendingUploadId))}
function setLocalPreview(file){if(previewProbe)clearTimeout(previewProbe);if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(file);previewMode="local";audio.src=objectUrl;audio.load();preview.style.display="block";previewStatus.textContent="กำลังเตรียม Local Preview…";previewProbe=setTimeout(()=>{if(previewMode==="local"&&audio.readyState===0)previewStatus.textContent="Local Preview ไม่พร้อมบน browser นี้ · Upload to Modify แล้วระบบจะใช้ Streaming Preview อัตโนมัติ"},1800)}
function useUploadedPreview(fileId){if(previewProbe)clearTimeout(previewProbe);previewProbe=null;if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=null}previewMode="stream";audio.pause();audio.src=API+"/audio/"+encodeURIComponent(fileId);audio.load();preview.style.display="block";previewStatus.textContent="Streaming Preview จาก Modify · กำลังเตรียมไฟล์ต้นฉบับ…"}
async function prepareLosslessPreview(fileId){if(previewPreparing||!fileId)return;previewPreparing=true;const expected=fileId;setFileRemoveBusy(true);previewStatus.textContent="Chrome Windows เล่น ALAC โดยตรงไม่ได้ · กำลังเตรียม Lossless FLAC Preview…";try{const result=await runProcessingJob("/preview",{fileId},job=>{previewStatus.textContent=job.status==="queued"?"กำลังรอคิว Lossless Preview · ลำดับ "+job.position:"กำลังแปลง ALAC → FLAC สำหรับ Preview…"});if(uploadedFileId!==expected)return;previewMode="converted";audio.pause();audio.src=API+result.url;audio.load();previewStatus.textContent="Lossless FLAC Preview จาก Modify · กำลังโหลด…"}catch(e){if(!e.stale&&uploadedFileId===expected)previewStatus.textContent="ไม่สามารถเตรียม Lossless Preview ได้ · "+e.message}finally{previewPreparing=false;if(uploadedFileId===expected)setFileRemoveBusy(false)}}
function showFile(file){if(input.disabled||fileRemove.disabled||pendingUploadId)return;processingEpoch++;exportButton.disabled=false;deleteExportButton.disabled=false;const ext=(file.name.split(".").pop()||"").toLowerCase();let message="";
if(!allowed.has(ext))message="รองรับเฉพาะ WAV, FLAC และ ALAC (.m4a)";else if(file.size>MAX_BYTES)message="ไฟล์ใหญ่เกิน 2,000 MB";
error.hidden=!message;error.textContent=message;result.hidden=Boolean(message);progress.hidden=true;uploadButton.disabled=Boolean(message);
if(message){selectedFile=null;input.value="";preview.style.display="none";audio.removeAttribute("src");audio.load();return}
selectedFile=file;uploadedFileId=null;previewPreparing=false;setFileLocation(false);fileRemove.disabled=false;activeTrackEnd=null;lastAnalysis=null;waveformPanel.hidden=true;trackResults.hidden=true;exportPanel.hidden=true;currentExportJobId=null;deleteExportButton.hidden=true;downloadList.replaceChildren();trackList.replaceChildren();analyzeButton.disabled=true;analysisStatus.hidden=true;uploadButton.disabled=false;uploadButton.textContent="Upload to Modify";nameEl.textContent=file.name;metaEl.textContent=(file.size/1000000).toFixed(2)+" MB · "+ext.toUpperCase();
setLocalPreview(file);
}
input.addEventListener("change",()=>input.files[0]&&showFile(input.files[0]));
["dragenter","dragover"].forEach(t=>zone.addEventListener(t,e=>{e.preventDefault();zone.classList.add("is-dragging")}));
["dragleave","drop"].forEach(t=>zone.addEventListener(t,e=>{e.preventDefault();zone.classList.remove("is-dragging")}));
zone.addEventListener("drop",e=>{const f=e.dataTransfer.files[0];if(f)showFile(f)});
async function jsonPost(url,data,headers={}){const r=await apiFetch(url,{method:"POST",headers:{"Content-Type":"application/json",...headers},body:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw new Error(j.error||("HTTP "+r.status));return j}
uploadButton.addEventListener("click",async()=>{if(!selectedFile)return;const view=processingEpoch;uploadButton.disabled=true;input.disabled=true;setFileRemoveBusy(true,"Uploading…");progress.hidden=false;setProgress(0,"กำลังสร้าง Upload session…");
try{if(pendingUploadId){await jsonPost("/upload/remove",{fileId:pendingUploadId});pendingUploadId=null}const init=await jsonPost("/upload/init",{name:selectedFile.name,size:selectedFile.size});if(view!==processingEpoch)return;pendingUploadId=init.uploadId;const chunkSize=init.chunkSize;let sent=0,index=0;
while(sent<selectedFile.size){const end=Math.min(sent+chunkSize,selectedFile.size),blob=selectedFile.slice(sent,end);const r=await apiFetch("/upload/chunk",{method:"POST",headers:{"Content-Type":"application/octet-stream","X-Upload-Id":init.uploadId,"X-Chunk-Index":String(index)},body:blob});const j=await r.json();if(view!==processingEpoch)return;if(!r.ok)throw new Error(j.error||("HTTP "+r.status));sent=end;index++;setProgress(sent/selectedFile.size*100,"ส่งแล้ว "+(sent/1000000).toFixed(1)+" / "+(selectedFile.size/1000000).toFixed(1)+" MB")}
const done=await jsonPost("/upload/complete",{uploadId:init.uploadId});if(view!==processingEpoch)return;pendingUploadId=null;uploadedFileId=done.fileId;setFileRemoveBusy(false);useUploadedPreview(done.fileId);setProgress(100,"UPLOAD COMPLETE · "+done.name+" · พร้อมสำหรับ Analyze");uploadButton.textContent="Uploaded to Modify";analyzeButton.disabled=false;
}catch(e){if(view!==processingEpoch)return;error.hidden=false;error.textContent="Upload failed: "+e.message;setProgress(0,"Upload ไม่สำเร็จ");uploadButton.disabled=false;setFileRemoveBusy(false)}finally{if(view===processingEpoch)input.disabled=false}
});
audio.addEventListener("loadedmetadata",()=>{if(previewProbe)clearTimeout(previewProbe);previewProbe=null;const s=Math.floor(audio.duration||0),m=Math.floor(s/60),ss=String(s%60).padStart(2,"0"),mode=previewMode==="converted"?"Lossless FLAC Preview from Modify":previewMode==="stream"?"Streaming from Modify":"Local playback";previewStatus.textContent="Duration "+m+":"+ss+" · "+mode});
audio.addEventListener("error",()=>{if(previewProbe)clearTimeout(previewProbe);previewProbe=null;const ext=((selectedFile?.name||nameEl.textContent).split(".").pop()||"").toLowerCase();if(previewMode==="stream"&&ext==="m4a"&&uploadedFileId){prepareLosslessPreview(uploadedFileId);return}previewStatus.textContent=previewMode==="stream"?"Streaming Preview ไม่สามารถเล่นไฟล์นี้ได้":previewMode==="converted"?"Lossless FLAC Preview ไม่สามารถเล่นได้":"Browser ไม่สามารถเล่น Local Preview ของไฟล์นี้ได้ · Upload to Modify เพื่อใช้ Streaming Preview"});
window.addEventListener("beforeunload",()=>{if(objectUrl)URL.revokeObjectURL(objectUrl)});
analyzeButton.addEventListener("click",async()=>{if(!uploadedFileId)return;analyzeButton.disabled=true;setFileRemoveBusy(true);analysisStatus.hidden=false;analysisState.textContent="ANALYZING…";analysisText.textContent="Analyze V2 กำลังประมวลผลบนเครื่อง Modify";error.hidden=true;const started=performance.now();
try{const data=await runProcessingJob("/analyze",{fileId:uploadedFileId},job=>{analysisState.textContent=job.status==="queued"?"WAITING IN QUEUE":"ANALYZING…";analysisText.textContent=job.status==="queued"?"รอคิวลำดับที่ "+job.position+" · ประมวลผลครั้งละหนึ่งงาน":"Analyze V2 กำลังประมวลผลบนเครื่อง Modify"});const elapsed=(performance.now()-started)/1000;analysisState.textContent="ANALYZE COMPLETE";analysisText.textContent=data.detections.length+" detections · "+(data.duration/60).toFixed(2)+" min · "+elapsed.toFixed(1)+" s";lastAnalysis=data;editableBoundaries=data.detections.map(d=>normalizeBoundary(Number(d.time))).filter(t=>Number.isFinite(t)&&t>0&&t<Number(data.duration)).sort((a,b)=>a-b);renderWaveform(data);renderTracks(data);exportPanel.hidden=false;exportStatus.textContent="พร้อม Export "+(data.detections.length+1)+" Tracks";downloadList.replaceChildren();analyzeButton.textContent="Re-analyze";analyzeButton.disabled=false;setFileRemoveBusy(false);window.lastAnalysis=data}
catch(e){if(e.stale)return;analysisState.textContent=e.cancelled?"CANCELLED":"ANALYZE FAILED";analysisText.textContent=e.message;analyzeButton.disabled=false;setFileRemoveBusy(false)}
});
function formatTime(seconds){seconds=Math.max(0,Number(seconds)||0);const h=Math.floor(seconds/3600),m=Math.floor(seconds%3600/60),s=Math.floor(seconds%60);return h?String(h).padStart(2,"0")+":"+String(m).padStart(2,"0")+":"+String(s).padStart(2,"0"):String(m).padStart(2,"0")+":"+String(s).padStart(2,"0")}
function formatEditTime(seconds){seconds=Math.max(0,Number(seconds)||0);const h=Math.floor(seconds/3600),m=Math.floor(seconds%3600/60),s=seconds-h*3600-m*60;return String(h).padStart(2,"0")+":"+String(m).padStart(2,"0")+":"+s.toFixed(3).padStart(6,"0")}
function parseEditTime(text){const p=String(text).trim().split(":");if(p.length!==3)return null;const h=Number(p[0]),m=Number(p[1]),s=Number(p[2]);if(!Number.isInteger(h)||h<0||!Number.isInteger(m)||m<0||m>59||!Number.isFinite(s)||s<0||s>=60)return null;return h*3600+m*60+s}
function normalizeBoundary(t){const sr=Number(lastAnalysis?.sample_rate)||0;return sr>0?Math.round(t*sr)/sr:t}
function stopTrackPlayback(){activeTrackEnd=null;if(activePlayButton){activePlayButton.classList.remove("is-playing");activePlayButton.textContent="Play";activePlayButton=null}}
function resetAudioWorkspaceSelection(){processingEpoch++;pendingUploadId=null;input.disabled=false;audio.pause();stopTrackPlayback();if(previewProbe)clearTimeout(previewProbe);previewProbe=null;previewPreparing=false;previewMode="local";selectedFile=null;uploadedFileId=null;lastAnalysis=null;currentExportJobId=null;editableBoundaries=[];delete window.lastAnalysis;if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=null}input.value="";audio.removeAttribute("src");audio.load();preview.style.display="none";result.hidden=true;progress.hidden=true;analysisStatus.hidden=true;waveformPanel.hidden=true;trackResults.hidden=true;exportPanel.hidden=true;error.hidden=true;trackList.replaceChildren();downloadList.replaceChildren();uploadButton.disabled=true;uploadButton.textContent="Upload to Modify";analyzeButton.disabled=true;analyzeButton.textContent="Analyze";deleteExportButton.hidden=true;deleteExportButton.disabled=false;waveformTime.textContent="00:00";setFileLocation(false);fileRemove.disabled=false}
fileRemove.addEventListener("click",async()=>{if(fileRemove.disabled)return;if(!uploadedFileId&&!pendingUploadId){resetAudioWorkspaceSelection();return}const view=processingEpoch,fileId=uploadedFileId||pendingUploadId,fileName=nameEl.textContent;if(!confirm("Remove from Modify?\n\n"+fileName))return;setFileRemoveBusy(true,"Removing…");error.hidden=true;try{await jsonPost("/upload/remove",{fileId});if(view===processingEpoch&&(uploadedFileId===fileId||pendingUploadId===fileId))resetAudioWorkspaceSelection();window.demoResourcesChanged();await loadUploads()}catch(e){if(view!==processingEpoch)return;error.hidden=false;error.textContent="Remove failed · "+e.message;if(uploadedFileId===fileId||pendingUploadId===fileId)setFileRemoveBusy(false)}});
function applyBoundaryEdit(index,text,input){const raw=parseEditTime(text),duration=Number(lastAnalysis?.duration)||0,previous=index?editableBoundaries[index-1]:0,next=index<editableBoundaries.length-1?editableBoundaries[index+1]:duration,value=raw===null?null:normalizeBoundary(raw);if(value===null||value<=previous||value>=next){input.classList.add("is-invalid");input.value=formatEditTime(editableBoundaries[index]);return}editableBoundaries[index]=value;input.classList.remove("is-invalid");stopTrackPlayback();renderTracks(lastAnalysis);renderWaveform(lastAnalysis);exportStatus.textContent="แก้ Boundary แล้ว · พร้อม Export "+(editableBoundaries.length+1)+" Tracks"}
function makeTimeInput(value,boundaryIndex,locked){const el=document.createElement("input");el.type="text";el.className="track-time-input";el.value=formatEditTime(value);el.inputMode="decimal";el.spellcheck=false;el.setAttribute("aria-label",locked?"Locked track boundary":"Editable track boundary");if(locked){el.readOnly=true;el.classList.add("is-locked")}else{el.title="HH:MM:SS.mmm";el.addEventListener("change",()=>applyBoundaryEdit(boundaryIndex,el.value,el));el.addEventListener("keydown",e=>{if(e.key==="Enter"){el.blur()}else if(e.key==="Escape"){el.value=formatEditTime(editableBoundaries[boundaryIndex]);el.blur()}})}return el}
function renderTracks(data){const starts=[0,...editableBoundaries],ends=[...editableBoundaries,Number(data.duration)];trackList.replaceChildren();starts.forEach((start,i)=>{const row=document.createElement("div");row.className="track-row";const title=document.createElement("strong");title.textContent="Track "+String(i+1).padStart(2,"0");const time=document.createElement("div");time.className="track-time track-time-edit";const startInput=makeTimeInput(start,i-1,i===0),arrow=document.createElement("span");arrow.textContent="→";arrow.className="track-time-arrow";const endInput=makeTimeInput(ends[i],i,i===ends.length-1);time.append(startInput,arrow,endInput);const actions=document.createElement("div");actions.className="track-actions";const play=document.createElement("button");play.type="button";play.className="track-play";play.textContent="Play";const stop=document.createElement("button");stop.type="button";stop.className="track-stop";stop.textContent="Stop";play.addEventListener("click",()=>{audio.pause();stopTrackPlayback();audio.currentTime=start;activeTrackEnd=ends[i];activePlayButton=play;play.classList.add("is-playing");play.textContent="Playing";audio.play().catch(()=>stopTrackPlayback())});stop.addEventListener("click",()=>{audio.pause();audio.currentTime=start;stopTrackPlayback();waveformTime.textContent=formatTime(start)});actions.append(play,stop);row.append(title,time,actions);trackList.append(row)});trackCount.textContent=starts.length+" Tracks";trackResults.hidden=false}
audio.addEventListener("timeupdate",()=>{if(activeTrackEnd!==null&&audio.currentTime>=activeTrackEnd-.05){audio.pause();audio.currentTime=activeTrackEnd;stopTrackPlayback()}});
audio.addEventListener("pause",()=>{if(activeTrackEnd!==null&&audio.currentTime<activeTrackEnd-.05)stopTrackPlayback()});
function renderWaveform(data){const mins=data.waveform?.minimum||[],maxs=data.waveform?.maximum||[];if(!mins.length||mins.length!==maxs.length)return;waveformPanel.hidden=false;requestAnimationFrame(()=>{const rect=waveformWrap.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2),w=Math.max(1,Math.round(rect.width)),h=Math.max(1,Math.round(rect.height));waveformCanvas.style.width=w+"px";waveformCanvas.style.height=h+"px";waveformCanvas.width=Math.round(w*dpr);waveformCanvas.height=Math.round(h*dpr);const c=waveformCanvas.getContext("2d");c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);c.strokeStyle="#8f969b";c.lineWidth=1;c.beginPath();for(let i=0;i<mins.length;i++){const x=i/(mins.length-1)*w,y1=h/2-Math.max(-1,Math.min(1,Number(maxs[i])||0))*(h*.43),y2=h/2-Math.max(-1,Math.min(1,Number(mins[i])||0))*(h*.43);c.moveTo(x,y1);c.lineTo(x,y2)}c.stroke();c.strokeStyle="#d5a94e";c.lineWidth=1;editableBoundaries.forEach(t=>{const x=Number(t)/Number(data.duration)*w;if(!Number.isFinite(x))return;c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke()})})}
waveformCanvas.addEventListener("pointerdown",e=>{if(!lastAnalysis)return;const r=waveformCanvas.getBoundingClientRect(),ratio=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),t=ratio*lastAnalysis.duration;stopTrackPlayback();audio.currentTime=t;waveformTime.textContent=formatTime(t)});
audio.addEventListener("timeupdate",()=>{if(lastAnalysis)waveformTime.textContent=formatTime(audio.currentTime)});
window.addEventListener("resize",()=>{if(lastAnalysis)renderWaveform(lastAnalysis)});
exportButton.addEventListener("click",async()=>{if(!uploadedFileId||!lastAnalysis)return;const epoch=processingEpoch;exportButton.disabled=true;setFileRemoveBusy(true);downloadList.replaceChildren();exportStatus.textContent="EXPORTING… "+(editableBoundaries.length+1)+" Tracks เป็น "+exportFormat.value.toUpperCase();try{const boundaries=[...editableBoundaries],out=await runProcessingJob("/export",{fileId:uploadedFileId,format:exportFormat.value,boundaries},job=>{exportStatus.textContent=job.status==="queued"?"รอคิว Export ลำดับที่ "+job.position+" · ประมวลผลครั้งละหนึ่งงาน":"EXPORTING… กำลังประมวลผลบนเครื่อง Modify"});currentExportJobId=out.jobId;deleteExportButton.hidden=false;deleteExportButton.disabled=false;exportStatus.textContent="EXPORT COMPLETE · "+out.success+" สำเร็จ · "+out.failed+" ล้มเหลว · ไฟล์หมดอายุหลัง 59 นาที";out.files.forEach(f=>{
const row=document.createElement("div");row.className="download-row";
const name=document.createElement("span");name.className="download-name";name.textContent=f.name;
const size=document.createElement("span");size.className="download-size";size.textContent=(f.size/1000000).toFixed(1)+" MB";
const link=document.createElement("a");link.className="download-link";
// A native navigation sends the HttpOnly session cookie and streams to the OS.
link.href=API+"/download/"+encodeURIComponent(out.jobId)+"/"+encodeURIComponent(f.name);
link.target="_blank";link.rel="noopener";link.textContent="Download";
link.setAttribute("aria-label","Download "+f.name);
row.append(name,size,link);downloadList.append(row);
})}catch(e){if(!e.stale)exportStatus.textContent=(e.cancelled?"CANCELLED · ":"EXPORT FAILED · ")+e.message}finally{if(epoch===processingEpoch){exportButton.disabled=false;setFileRemoveBusy(false)}}});
deleteExportButton.addEventListener("click",async()=>{if(!currentExportJobId||deleteExportButton.disabled)return;const deleting=currentExportJobId,view=processingEpoch;deleteExportButton.disabled=true;try{await jsonPost("/export/delete",{jobId:deleting});window.demoResourcesChanged();if(view!==processingEpoch||currentExportJobId!==deleting)return;currentExportJobId=null;downloadList.replaceChildren();deleteExportButton.hidden=true;exportStatus.textContent="EXPORT FILES DELETED · พื้นที่บน Modify ถูกคืนแล้ว"}catch(e){if(view!==processingEpoch||currentExportJobId!==deleting)return;exportStatus.textContent="DELETE FAILED · "+e.message;deleteExportButton.disabled=false}});

const uploadsList=document.querySelector("#uploads-list"),uploadsStatus=document.querySelector("#uploads-status"),refreshUploads=document.querySelector("#refresh-uploads");
function uploadSize(n){return n>=1e9?(n/1e9).toFixed(2)+" GB":(n/1e6).toFixed(2)+" MB"}
function selectUploadedFile(f){if(input.disabled||pendingUploadId)return;processingEpoch++;deleteExportButton.disabled=false;uploadedFileId=f.fileId;selectedFile=null;previewPreparing=false;lastAnalysis=null;currentExportJobId=null;stopTrackPlayback();nameEl.textContent=f.name;metaEl.textContent=uploadSize(f.size)+" · "+(f.name.split(".").pop()||"").toUpperCase();setFileLocation(true);fileRemove.disabled=false;useUploadedPreview(f.fileId);waveformPanel.hidden=true;trackResults.hidden=true;exportPanel.hidden=true;analysisStatus.hidden=true;downloadList.replaceChildren();trackList.replaceChildren();analyzeButton.disabled=false;analyzeButton.textContent="Analyze";uploadButton.disabled=true;result.hidden=false;progress.hidden=false;setProgress(100,"ไฟล์อยู่บน Modify แล้ว · พร้อมสำหรับ Analyze");result.scrollIntoView({behavior:"smooth",block:"center"})}
async function loadUploads(){if(!uploadsList)return;const auth=window.demoAuth,view=processingEpoch,request=++uploadsRequest;uploadsStatus.textContent="Loading uploaded files...";try{const r=await apiFetch("/uploads",{cache:"no-store"}),j=await r.json();if(!r.ok)throw new Error(j.error||("HTTP "+r.status));if(auth!==window.demoAuth||view!==processingEpoch||request!==uploadsRequest)return;uploadsList.replaceChildren();const files=j.files||[];if(uploadedFileId&&!files.some(f=>f.fileId===uploadedFileId))resetAudioWorkspaceSelection();uploadsStatus.textContent=files.length?files.length+" uploaded file(s) on Modify":"No uploaded files on Modify";files.forEach(f=>{const row=document.createElement("div");row.className="upload-file-row";row.dataset.fileId=f.fileId;const n=document.createElement("strong");n.textContent=f.name;const m=document.createElement("span");m.className="upload-file-meta";m.textContent=uploadSize(f.size)+" · "+new Date(f.modified).toLocaleString();const actions=document.createElement("div");actions.className="upload-file-actions";const analyze=document.createElement("button");analyze.type="button";analyze.className="upload-analyze-button";analyze.textContent="Analyze";analyze.addEventListener("click",()=>selectUploadedFile(f));const del=document.createElement("button");del.type="button";del.className="upload-delete-button";del.textContent="Delete";del.addEventListener("click",async()=>{if(!confirm("Delete uploaded file?\n\n"+f.name))return;del.disabled=true;del.textContent="Deleting...";try{await jsonPost("/upload/remove",{fileId:f.fileId});if(uploadedFileId===f.fileId)resetAudioWorkspaceSelection();window.demoResourcesChanged();await loadUploads()}catch(e){uploadsStatus.textContent="Delete failed · "+e.message;del.disabled=false;del.textContent="Delete"}});actions.append(analyze,del);const info=document.createElement("div");info.className="upload-file-info";info.append(n,m);row.append(info,actions);uploadsList.append(row)})}catch(e){uploadsStatus.textContent="Unable to load uploads · "+e.message}}
refreshUploads?.addEventListener("click",loadUploads);

window.demoResourceView=()=>({fileId:uploadedFileId,exportId:currentExportJobId,epoch:processingEpoch});
window.addEventListener('demo-resources',({detail:{view,state}})=>{
 if(view.epoch!==processingEpoch)return;
 const shown=[...uploadsList.children].map(el=>el.dataset.fileId);if(shown.length!==state.files.length||shown.some(id=>!state.files.includes(id)))loadUploads();
 if(view.fileId&&view.fileId===uploadedFileId&&!state.files.includes(view.fileId)){resetAudioWorkspaceSelection();loadUploads()}
 else if(view.exportId&&view.exportId===currentExportJobId&&!state.exports.includes(view.exportId)){currentExportJobId=null;downloadList.replaceChildren();deleteExportButton.hidden=true;exportStatus.textContent='Export files deleted or expired'}
});
window.addEventListener('demo-delete-completed',()=>{loadUploads();refreshProcessingJobs()});
